<script lang="ts">import {line,colors} from '../charts';let {values,w=120,h=40,color=colors.ink,band=null,fill=true,min,max}:{values:(number|null)[],w?:number,h?:number,color?:string,band?:[number,number]|null,fill?:boolean,min?:number,max?:number}=$props();const id=Math.random().toString(36).slice(2);let all=$derived([...values.filter((v):v is number=>v!=null),...(band??[])]),lo=$derived(min??Math.min(...all)),hi=$derived(max??Math.max(...all)),path=$derived(line(values,w,h,lo,hi)),end=$derived(values.length?values[values.length-1]:null),y=(v:number)=>h-4-(v-lo)/(hi-lo||1)*(h-8);</script><svg width={w} height={h} viewBox={`0 0 ${w} ${h}`} style="display:block;max-width:100%" aria-hidden="true">{#if path}{#if band}<rect x="0" y={y(band[1])} width={w} height={Math.max(0,y(band[0])-y(band[1]))} rx="5" fill="#fff" opacity=".13"/>{/if}{#if fill}<defs><linearGradient id={id} x1="0" y1="0" x2="0" y2="1"><stop stop-color={color} stop-opacity=".32"/><stop offset="1" stop-color={color} stop-opacity="0"/></linearGradient></defs><path d={`${path}L${w-4},${h}L4,${h}Z`} fill={`url(#${id})`}/>{/if}<path d={path} fill="none" stroke={color} stroke-width="2.2" stroke-linecap="round"/>{#if end!=null}<circle cx={w-4} cy={y(end)} r="3.6" fill={color} stroke="#0B0F1A" stroke-width="2"/>{/if}{/if}</svg>